checkItem(actual, expected) {
  Assert.equal(
    BrowserTestUtils.isHidden(actual),
    !!expected.hidden,
    `${actual.id} hidden`
  );
  if (!expected.hidden && actual.localName != "menugroup") {
    Assert.equal(
      actual.disabled,
      !!expected.disabled,
      `${actual.id} disabled`
    );
  }
  if (expected.checked) {
    Assert.ok(actual.hasAttribute("checked"), `${actual.id} checked`);
  } else if (["checkbox", "radio"].includes(actual.getAttribute("type"))) {
    Assert.ok(!actual.hasAttribute("checked"), `${actual.id} not checked`);
  }
  if (expected.l10nID) {
    const attributes = actual.ownerDocument.l10n.getAttributes(actual);
    Assert.equal(attributes.id, expected.l10nID, `${actual.id} L10n string`);
    Assert.deepEqual(
      attributes.args,
      expected.l10nArgs ?? null,
      `${actual.id} L10n args`
    );
  }
}

